    xlabel=$x$,
    ylabel=$y$,
    zlabel=$z$,
    title={Hyperbolic Paraboloid with Traces: $y = z^2 - x^2$},
    view={-50}{25},
    colormap/viridis,
    grid=none,
    axis lines=center,
    domain=-3:3,
    y domain=-3:3,
    samples=40,
    samples y=40,
    zmin=-3, zmax=3,
    xmin=-3, xmax=3,
    ymin=-9, ymax=9,
    width=12cm,
    height=10cm,
]
